// fayl: components/Alert.tsx
import styles from "./Alert.module.css"

type Props = { kind: "info" | "error"; dismissible?: boolean; children: React.ReactNode }

export function Alert({ kind, dismissible, children }: Props) {
  const className = [
    styles.alert,
    kind === "error" && styles.error,
    dismissible && styles.dismissible,
  ]
    .filter(Boolean)
    .join(" ")

  return <div role="alert" className={className}>{children}</div>
}

// fayl: lib/cx.ts
export function cx(...parts: (string | false | null | undefined)[]) {
  return parts.filter(Boolean).join(" ")
}

// fayl: components/Tab.tsx
import { cx } from "@/lib/cx"
import styles from "./Tab.module.css"

export function Tab({ label, active, disabled }: { label: string; active?: boolean; disabled?: boolean }) {
  return (
    <button className={cx(styles.tab, active && styles.active, disabled && styles.disabled)} disabled={disabled}>
      {label}
    </button>
  )
}

// fayl: components/Step.tsx
import clsx from "clsx"
import styles from "./Step.module.css"

type Status = "done" | "current" | "todo"

export function Step({ title, status }: { title: string; status: Status }) {
  return (
    <li
      className={clsx(styles.step, {
        [styles.done]: status === "done",
        [styles.current]: status === "current",
      })}
    >
      {title}
    </li>
  )
}

